custom_functions.get_prev_month_year:
from datetime import datetime
def get_prev_month_year():
    try:
        now = datetime.now()
        prev_month = now.month - 1 or 12
        year = now.year - 5 if now.month > 1 else now.year - 6
        return f'{prev_month:02d}/{year}'
    except Exception as e:
        print(f'get_prev_month_year() - Error in function: {e}')
        return None

