custom_functions.get_str_between:
import random
import string
def get_str_between(start_str, total_length, case='mixed'):
    try:
        start_length = len(start_str)
        if start_length > total_length:
            total_length += start_length
        remaining_length = total_length - start_length
        if case.lower() == 'upper':
            random_part = ''.join(random.choices(string.ascii_uppercase + string.digits, k=remaining_length))
        elif case.lower() == 'lower':
            random_part = ''.join(random.choices(string.ascii_lowercase + string.digits, k=remaining_length))
        else:
            random_part = ''.join(random.choices(string.ascii_letters + string.digits, k=remaining_length))
        return start_str + random_part
    except Exception as e:
        print(f'get_str_between() - Error in function: {e}')
        return None

